function qp_scientist_albert_einstein_import_data() {
 return json_decode('[{"slug": "albert-einstein", "locale": "fa-IR", "title": "زندگی‌نامه آلبرت اینشتین | از فوتوالکتریک تا نسبیت عام", "seo_title": "زندگی‌نامه آلبرت اینشتین | نوبل و نسبیت عام", "meta_description": "زندگی‌نامه کامل آلبرت اینشتین از تولد ۱۴ مارس ۱۸۷۹ تا نوبل ۱۹۲۱ فوتوالکتریک و نسبیت ۱۹۰۵ و ۱۹۱۵ با ۱۰ منبع معتبر سالم.", "focus_keyword": "زندگی‌نامه آلبرت اینشتین", "content_html": "<!DOCTYPE html>\\n<html lang=\\"fa-IR\\" dir=\\"rtl\\">\\n<head>\\n<meta charset=\\"UTF-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n<title>زندگی‌نامه آلبرت اینشتین | از فوتوالکتریک تا نسبیت عام</title>\\n<meta name=\\"description\\" content=\\"زندگی‌نامه کامل آلبرت اینشتین از تولد ۱۴ مارس ۱۸۷۹ در اولم تا نوبل ۱۹۲۱ برای فوتوالکتریک، نسبیت خاص ۱۹۰۵ و عام ۱۹۱۵، نامه روزولت، دین و اخلاق با ۱۲ منبع معتبر.\\">\\n<link rel=\\"canonical\\" href=\\"https://qpedia.ir/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"fa\\" href=\\"https://qpedia.ir/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"en\\" href=\\"https://qpedia.ir/en/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"x-default\\" href=\\"https://qpedia.ir/scientists/albert-einstein/\\">\\n<link href=\\"https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css\\" rel=\\"stylesheet\\">\\n<style>\\n  body{font-family:Vazirmatn,Tahoma,sans-serif;line-height:2.2;font-size:17.5px;color:#1e293b;max-width:840px;margin:0 auto;padding:32px 20px;background:#fff}\\n  h1{font-size:33px;font-weight:900;line-height:1.35;margin:0 0 22px;color:#0f172a}\\n  h2{font-size:24px;font-weight:800;margin:60px 0 18px;padding-bottom:10px;border-bottom:2.5px solid #e2e8f0;color:#0f172a}\\n  h3{font-size:19px;font-weight:700;margin:34px 0 14px;color:#1e293b}\\n  p{margin:0 0 10px;text-align:justify}\\n  a{color:#1d4ed8;text-decoration:none;border-bottom:1px dotted #1d4ed8}\\n  .qpedia-lead{background:#f8fafc;border-right:5px solid #3b82f6;padding:20px 22px;border-radius:12px;margin:26px 0 34px;font-size:18px}\\n  .qpedia-infobox{border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.06);margin:30px 0}\\n  .qpedia-infobox h3{margin:0;padding:14px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0}\\n  .qpedia-infobox th{text-align:right;padding:11px 20px;background:#fcfcfd;border-bottom:1px solid #f1f5f9;width:150px;font-weight:700;color:#475569;font-size:14px}\\n  .qpedia-infobox td{padding:11px 20px;border-bottom:1px solid #f1f5f9;font-size:14.5px}\\n  .table-wrapper{overflow-x:auto;border:1px solid #e5e7eb;border-radius:10px;margin:22px 0}\\n  .table-wrapper table{width:100%;min-width:560px;border-collapse:collapse;font-size:14.5px}\\n  .table-wrapper th{background:#f8fafc;padding:12px;border-bottom:2px solid #e2e8f0;text-align:right}\\n  .table-wrapper td{padding:11px 12px;border-bottom:1px solid #f1f5f9}\\n  .qpedia-quote{border-right:5px solid #10b981;background:#f0fdf4;padding:18px 22px;border-radius:12px;margin:30px 0;font-style:italic;font-size:17px}\\n  .qpedia-newspaper{border:1px dashed #d97706;background:#fffbeb;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-media{border:1px solid #e2e8f0;background:#f8fafc;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-faq{background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:24px;margin:30px 0}\\n  .qpedia-faq-item{margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #e2e8f0}\\n  .qpedia-faq-item:last-child{border:none;margin:0;padding:0}\\n  .qpedia-faq-q{font-weight:800;margin-bottom:8px}\\n  .disclaimer{background:#fef2f2;border-right:5px solid #ef4444;padding:12px 16px;border-radius:10px;font-size:13.5px;color:#57534e;margin:12px 0 20px}\\n  .author-box{background:#f1f5f9;padding:14px 18px;border-radius:10px;font-size:13.5px;margin:24px 0;border:1px solid #e2e8f0}\\n  .qpedia-para-source{font-size:12px;color:#94a3b8;margin:-4px 0 22px;line-height:1.7}\\n  .qpedia-para-source a{color:#94a3b8;border-bottom:1px dotted #cbd5e1;text-decoration:none}\\n  .qpedia-para-source a:hover{color:#64748b}\\n  @media(max-width:640px){body{padding:20px 14px;font-size:15.5px}h1{font-size:26px}h2{font-size:20px}.qpedia-infobox th{width:110px}}\\n</style>\\n</head>\\n<body>\\n\\n<h1>زندگی‌نامه آلبرت اینشتین | از فوتوالکتریک تا نسبیت عام</h1>\\n\\n<div class=\\"author-box\\">\\n<strong>نویسنده:</strong> تحریریه Qpedia — بازبینی علمی دکتر فیزیک نظری (شریف) — <strong>انتشار:</strong> 2026-09-21 — <strong>بروزرسانی:</strong> 2026-09-21 — <a href=\\"https://qpedia.ir/about/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">درباره ما</a> | <a href=\\"https://qpedia.ir/contact/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">تماس</a>\\n</div>\\n\\n<div class=\\"qpedia-lead\\">\\nآلبرت اینشتین کارمندی در اداره ثبت اختراع برن بود که در یک سال، چهار بار فیزیک را بازنوشت. او در ۱۹۰۵ نشان داد نور بسته‌بسته است، اتم‌ها واقعی‌اند، زمان کش می‌آید و جرم همان انرژی منجمد است. ده سال بعد گرانش را از نیرو به هندسه تبدیل کرد و جهان را خم کرد. همین دو جهش، از فوتوالکتریک تا نسبیت عام، پایه تمام فناوری امروز از GPS تا پنل خورشیدی شد.\\n</div>\\n\\n<div class=\\"qpedia-infobox\\">\\n<h3>شناسنامه سریع</h3>\\n<table>\\n<tr><th>نام کامل</th><td>Albert Einstein</td></tr>\\n<tr><th>تولد</th><td>۱۴ مارس ۱۸۷۹ — اولم، وورتمبرگ، آلمان</td></tr>\\n<tr><th>وفات</th><td>۱۸ آوریل ۱۹۵۵ — پرینستون، نیوجرسی، آمریکا، ۷۶ ساله</td></tr>\\n<tr><th>کشور تولد</th><td>آلمان</td></tr>\\n<tr><th>کشور تحصیل</th><td>سوئیس — ETH زوریخ و دانشگاه زوریخ</td></tr>\\n<tr><th>معروف به</th><td>اثر فوتوالکتریک E=hν، نسبیت خاص و عام، E=mc²، حرکت براونی</td></tr>\\n<tr><th>جایزه شاخص</th><td>نوبل فیزیک ۱۹۲۱ (اهدا ۱۹۲۲) برای قانون فوتوالکتریک</td></tr>\\n<tr><th>دین</th><td>یهودی سکولار، آگنوستیک با گرایش اسپینوزایی — نامه ۱۹۵۴ به گوتکایند</td></tr>\\n</table>\\n</div>\\n\\n<h2>کودکی در اولم و مونیخ: قطب‌نما و ویولن</h2>\\n<p>آلبرت اینشتین در ۱۴ مارس ۱۸۷۹ در اولم آلمان به دنیا آمد، در خانواده‌ای یهودی سکولار و متوسط. پدرش هرمان اینشتین در ابتدا فروشنده پر و بعد صاحب کارخانه الکتروشیمی بود و مادرش پاولینه کخ خانه را اداره می‌کرد. خانواده آیین مذهبی خاصی را رعایت نمی‌کرد اما هویت یهودی‌اش را انکار هم نمی‌کرد. آلبرت یک خواهر کوچک‌تر به نام مایا داشت که دو سال بعد به دنیا آمد و تا پایان عمر نزدیک‌ترین همرازش ماند.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Britannica – Albert Einstein birth 14 March 1879 Ulm | Nobel Facts – Einstein 1879-1955</div>\\n\\n<p>دو خاطره کودکی مسیرش را ساخت. در ۵ سالگی پدرش یک قطب‌نما به او داد و او ساعت‌ها خیره به عقربه‌ای بود که بدون تماس می‌چرخید؛ اولین مواجهه با نیروی نامرئی. در ۱۲ سالگی کتاب کوچک هندسه‌ای به دستش رسید که آن را «کتاب مقدس هندسه» نامید و شیفته این شد که با چند اصل ساده می‌توان حقیقت‌های ابدی ساخت. همزمان ویولن می‌نواخت و موتسارت را تا آخر عمر هر روز تمرین می‌کرد. در لوییتپولد گیمنازیوم مونیخ اما از نظام پروسی خسته بود؛ نظم پادگانی و حفظ کردن طوطی‌وار، چیزی که بعدها گفت خلاقیت را خفه می‌کند. معلمی حتی به او گفت هرگز به جایی نمی‌رسد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Britannica – childhood compass violin, Luitpold Gymnasium</div>\\n\\n<p>۱۸۹۴ کارخانه پدر در مونیخ شکست خورد و خانواده به میلان رفت. آلبرت در پانسیون مونیخ تنها ماند و شش ماه بعد فرار کرد و با قطار خودش را به والدینش رساند. در ۱۸۹۶ تابعیت آلمان را ترک کرد و چند سال بی‌تابعیت بود تا در ۱۹۰۱ شهروند سوئیس شد؛ تابعتی که تا پایان عمر نگه داشت حتی بعد از آمریکایی شدن.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – moved to Milan 1894, stateless 1896, Swiss 1901</div>\\n\\n<h2>تحصیلات: از مردودی تا دکترا</h2>\\n<p>اینشتین در ۱۸۹۵ در آزمون ورودی پلی‌تکنیک زوریخ رد شد، اما نمره ریاضی‌اش آنقدر عالی بود که مدیر مدرسه آرااو در سوئیس او را پذیرفت. ۱۸۹۶ دیپلم گرفت و وارد ETH زوریخ شد، جایی که با میلوا ماریچ، همکلاسی صرب، و میشل بسو، دوست مادام‌العمرش، آشنا شد. استادش هرمان مینکوفسکی بعدها نسبیت را به زبان هندسی ترجمه کرد، هرچند آن زمان اینشتین را دانشجوی تنبل اما با ایده‌های جسورانه می‌دید. ۱۹۰۰ با مدرک معلمی فیزیک و ریاضی فارغ‌التحصیل شد و ۱۹۰۵ دکترایش را از دانشگاه زوریخ با تز «تعیین جدید ابعاد مولکولی» گرفت.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – ETH Zurich 1896-1900, PhD 1905 University of Zurich</div>\\n\\n<p>۱۹۰۲ به عنوان کارشناس درجه سه در اداره ثبت اختراع برن استخدام شد. کارش بررسی اختراعات الکترومغناطیسی بود، اما در کشوی میزش معادلات نور را حل می‌کرد. همین شغل آرام به او وقت داد تا بدون فشار آکادمیک، عمیق‌ترین سوالات را بپرسد: اگر با سرعت نور حرکت کنی، نور را چگونه می‌بینی؟ همین سوال کودکی بعدها نسبیت شد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Nobel Biographical – patent office Bern 1902</div>\\n\\n<h2>سال معجزه ۱۹۰۵: چهار مقاله که جهان را تکان داد</h2>\\n<p>سال ۱۹۰۵ را «annus mirabilis» یا سال معجزه می‌نامند. اینشتین ۲۶ ساله در Annalen der Physik چهار مقاله منتشر کرد که هر کدام یک شاخه فیزیک را ساخت. این اتفاق در تاریخ علم بی‌سابقه است که یک نفر در یک سال، هم کوانتوم نور، هم اثبات اتم، هم نسبیت زمان و هم E=mc² را بدهد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – miracle year 1905 four papers</div>\\n\\n<h3>۱. فوتوالکتریک — نور ذره است — مارس ۱۹۰۵</h3>\\n<p>مقاله اول ۱۷ مارس ۱۹۰۵ با عنوان «دیدگاهی اکتشافی درباره تولید و تبدیل نور» آمد. اینشتین گفت نور از بسته‌های انرژی E=hν ساخته شده، همان ایده‌ای که پلانک برای نوسانگرها گفته بود اما اینشتین آن را به خود نور تعمیم داد. این توضیح می‌داد چرا برای کندن الکترون از فلز، فرکانس نور مهم است نه شدت آن. رابرت میلیکان ۱۱ سال بعد با آزمایش‌های دقیق آن را تایید کرد و اینشتین برای همین قانون، نوبل فیزیک ۱۹۲۱ را برد که در ۱۹۲۲ اهدا شد. امروز همین قانون اساس سلول خورشیدی و سنسور دوربین گوشی توست.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Einstein 1905a – photoelectric Annalen DOI | Nobel 1921 – photoelectric effect | Nobel Stories – smartphone camera</div>\\n\\n<h3>۲. حرکت براونی — اتم واقعی است — می ۱۹۰۵</h3>\\n<p>مقاله دوم ۱۱ می ۱۹۰۵ حرکت تصادفی دانه گرده در آب را با برخورد مولکول‌ها توضیح داد و فرمولی برای میانگین جابجایی داد که عدد آووگادرو را قابل اندازه‌گیری می‌کرد. ژان پرن در ۱۹۰۸ با میکروسکوپ آن را تایید کرد و شک ۲۰۰۰ ساله به وجود اتم پایان یافت. اینشتین با یک معادله، فلسفه را به آزمایشگاه آورد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – Brownian motion 1905 proof of atoms</div>\\n\\n<h3>۳. نسبیت خاص و E=mc² — ژوئن و سپتامبر ۱۹۰۵</h3>\\n<p>مقاله سوم ۳۰ ژوئن ۱۹۰۵ «الکترودینامیک اجسام متحرک» دو اصل داشت: قوانین فیزیک در همه چارچوب‌های لخت یکسان‌اند و سرعت نور در خلا برای همه ناظران ثابت است. از این دو، اتساع زمان و انقباض طول نتیجه شد. مقاله چهارم سپتامبر ۱۹۰۵ یک نتیجه فرعی بود: جرم و انرژی هم‌ارزند، E=mc². این فرمول بعدها انرژی هسته‌ای را توضیح داد، اما خود اینشتین همیشه تاکید می‌کرد که این فقط یک نتیجه هندسی از نسبیت است، نه دستور ساخت بمب.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Einstein 1905c – special relativity DOI | Britannica – E=mc2 mass-energy</div>\\n\\n<h3>۴. نسبیت عام — گرانش خمیدگی فضازمان — ۱۹۱۵</h3>\\n<p>اینشتین ۱۰ سال روی تعمیم نسبیت کار کرد و در ۲۵ نوامبر ۱۹۱۵ معادلات میدان را کامل کرد: ماده به فضازمان می‌گوید چگونه خم شود، فضازمان به ماده می‌گوید چگونه حرکت کند. پیش‌بینی کرد نور ستاره‌ای که از کنار خورشید می‌گذرد ۱.۷۵ ثانیه قوس خم می‌شود. آرتور ادینگتون در خورشیدگرفتگی ۲۹ می ۱۹۱۹ در آفریقا و برزیل این خمیدگی را اندازه گرفت و تایمز لندن ۷ نوامبر ۱۹۱۹ تیتر زد «انقلاب در علم — ایده‌های نیوتن سرنگون شد». اینشتین یک‌شبه مشهورترین دانشمند جهان شد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Britannica – general relativity 1915, Eddington 1919 eclipse | Stanford Encyclopedia – Einstein 1915 field equations</div>\\n\\n<h2>جوایز و افتخارات</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>سال</th><th>جایزه</th><th>دلیل</th></tr>\\n<tr><td>۱۹۲۱ (اهدا ۱۹۲۲)</td><td>نوبل فیزیک</td><td>کشف قانون اثر فوتوالکتریک</td></tr>\\n<tr><td>۱۹۲۵</td><td>مدال کاپلی</td><td>انجمن سلطنتی لندن</td></tr>\\n<tr><td>۱۹۲۹</td><td>مدال ماکس پلانک</td><td>انجمن فیزیک آلمان</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">منابع: Nobel 1921 summary | Britannica – Copley Medal 1925</div>\\n\\n<h2>زندگی شخصی، دین و اخلاق</h2>\\n<p>اینشتین ۱۹۰۳ با میلوا ماریچ ازدواج کرد؛ لیزرل ۱۹۰۲، هانس آلبرت ۱۹۰۴ و ادوارد ۱۹۱۰ فرزندانشان بودند. ازدواج در ۱۹۱۹ به طلاق انجامید و همان سال با دخترعمویش الزا لوونثال ازدواج کرد که تا مرگ الزا در ۱۹۳۶ ادامه داشت. او به شوخ‌طبعی، فروتنی و بی‌نظمی معروف بود؛ موهای ژولیده، کت چرمی و ویولن همیشه همراهش بود. با چارلی چاپلین دوست بود و می‌گفت تخیل مهم‌تر از دانش است.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – marriages Mileva Maric, Elsa Lowenthal</div>\\n\\n<p>از نظر دینی در خانواده یهودی سکولار بزرگ شد. در ۱۲ سالگی دوره مذهبی کوتاهی داشت اما بعدها گفت «من به خدای اسپینوزا باور دارم که خود را در هارمونی جهان نشان می‌دهد». در نامه معروف ۳ ژانویه ۱۹۵۴ به اریک گوتکایند نوشت «کلمه خدا برای من چیزی جز بیان ضعف انسانی نیست». خود را آگنوستیک می‌خواند نه آتئیست مبارز و جمله‌اش معروف است: «علم بدون دین لنگ است، دین بدون علم کور است».</p>\\n<div class=\\"qpedia-para-source\\">منبع: Stanford Encyclopedia – Einstein religion Spinoza, Gutkind letter 1954</div>\\n\\n<p>از نظر اخلاقی صلح‌طلب بود و ۱۹۱۴ مانیفست ضد جنگ امضا کرد. ۱۹۳۳ وقتی هیتلر به قدرت رسید در آمریکا بود و نازی‌ها کتاب‌هایش را سوزاندند و «فیزیک یهودی» خواندند. او از آکادمی پروس استعفا داد و به موسسه مطالعات پیشرفته پرینستون رفت. ۲ اوت ۱۹۳۹ نامه‌ای که لئو زیلارد نوشته بود را امضا کرد و به روزولت هشدار داد آلمان ممکن است بمب اتمی بسازد؛ نامه‌ای که به پروژه منهتن انجامید اما خود او در آن کار نکرد. بعدها گفت امضای آن نامه «یک اشتباه بزرگ» بود. پس از جنگ برای خلع سلاح هسته‌ای و حقوق مدنی سیاه‌پوستان آمریکا فعالیت کرد و ۱۹۵۲ پیشنهاد ریاست اسرائیل را رد کرد.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Britannica – pacifism, Nazi book burning 1933, Roosevelt letter 1939, civil rights | Nobel Biographical – Princeton 1933, US citizen 1940</div>\\n\\n<p>۱۸ آوریل ۱۹۵۵ بر اثر پارگی آنوریسم آئورت شکمی در پرینستون درگذشت. او جراحی را رد کرد و گفت «می‌خواهم وقتی خودم می‌خواهم بروم، مصنوعی طولانی کردن زندگی بی‌مزه است». تا ساعات آخر روی نظریه میدان یکپارچه کار می‌کرد.</p>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – death 18 April 1955 aneurysm</div>\\n\\n<h2>داستان‌ها با هشدار سند</h2>\\n<p>می‌گویند اینشتین در مدرسه ریاضی ضعیف بود و مردود شد. این روایت نادرست است؛ او در ریاضی نابغه بود و ۱۸۹۵ با نمره عالی ریاضی وارد آرااو شد، فقط در زبان و زیست ضعیف بود.</p>\\n<div class=\\"disclaimer\\">این روایت در فرهنگ عامه رایج است اما اسناد مدرسه خلاف آن را نشان می‌دهد — نادرست.</div>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – myth failed math debunked</div>\\n\\n<p>می‌گویند جمله «تخیل مهم‌تر از دانش است» از اوست. این جمله در مصاحبه ۱۹۲۹ با Saturday Evening Post آمده اما متن دقیق با واسطه نقل شده و به عنوان نقل قول رایج پذیرفته می‌شود.</p>\\n<div class=\\"disclaimer\\">نقل قول با واسطه ثبت شده — به عنوان روایت رایج پذیرفته می‌شود، نه سند کلمه‌به‌کلمه.</div>\\n\\n<h2>نقل قول‌ها و روزنامه‌ها</h2>\\n<div class=\\"qpedia-quote\\">\\n«خدا تاس نمی‌اندازد.» — نامه به ماکس بورن، ۴ دسامبر ۱۹۲۶، درباره تفسیر احتمالی کوانتوم\\n</div>\\n<div class=\\"qpedia-para-source\\">منبع: Stanford – Einstein Born letter 1926 God does not play dice</div>\\n\\n<div class=\\"qpedia-newspaper\\">\\n📰 تایمز لندن — ۷ نوامبر ۱۹۱۹: «انقلاب در علم — نظریه جدید جهان — ایده‌های نیوتن سرنگون شد.» گزارش تایید نسبیت عام توسط ادینگتون.\\n</div>\\n<div class=\\"qpedia-para-source\\">منبع: Britannica – Times 1919 headline</div>\\n\\n<div class=\\"qpedia-media\\">\\n🔬 APS Physics ۲۰۲۵ صدمین سال فوتوالکتریک را «تولد فوتون» نامید و نوشت امروز سلول خورشیدی و دوربین گوشی مدیون همان قانون است.\\n</div>\\n<div class=\\"qpedia-para-source\\">منابع: APS Physics 2025 – Quantum Milestones Einstein photoelectric | Nobel Stories – solar cell camera</div>\\n\\n<h2>میراث در جیب شما</h2>\\n<p>بدون نسبیت خاص، ساعت ماهواره GPS روزانه ۷ میکروثانیه عقب می‌ماند و بدون نسبیت عام ۴۵ میکروثانیه جلو می‌افتد؛ بدون هر دو، موقعیت‌یاب بعد از یک روز کیلومترها خطا می‌دهد. بدون فوتوالکتریک دوربین و پنل خورشیدی نیست و معادله لیزر اینشتین در ۱۹۱۷ اساس فیبر نوری است. امواج گرانشی که LIGO در ۲۰۱۵ دید، همان چین‌خوردگی فضازمانی است که اینشتین در ۱۹۱۵ پیش‌بینی کرده بود.</p>\\n<div class=\\"qpedia-para-source\\">منابع: Britannica – GPS relativity, LIGO gravitational waves</div>\\n\\n<h2>خط زمان دقیق</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>تاریخ</th><th>رویداد</th></tr>\\n<tr><td>۱۸۷۹-۰۳-۱۴</td><td>تولد اولم</td></tr>\\n<tr><td>۱۹۰۵-۰۳-۱۷</td><td>فوتوالکتریک E=hν</td></tr>\\n<tr><td>۱۹۰۵-۰۶-۳۰</td><td>نسبیت خاص</td></tr>\\n<tr><td>۱۹۱۵-۱۱-۲۵</td><td>معادلات نسبیت عام</td></tr>\\n<tr><td>۱۹۱۹-۰۵-۲۹</td><td>تایید ادینگتون</td></tr>\\n<tr><td>۱۹۲۱ (اهدا ۱۹۲۲)</td><td>نوبل فیزیک</td></tr>\\n<tr><td>۱۹۳۳</td><td>مهاجرت به پرینستون</td></tr>\\n<tr><td>۱۹۳۹-۰۸-۰۲</td><td>نامه به روزولت</td></tr>\\n<tr><td>۱۹۵۵-۰۴-۱۸</td><td>وفات پرینستون</td></tr>\\n</table></div>\\n\\n<h2>سوءتفاهم‌های رایج</h2>\\n<p><strong>۱. در مدرسه مردود بود:</strong> نه، در ریاضی نابغه بود.</p>\\n<p><strong>۲. بمب اتم را ساخت:</strong> نه، در منهتن کار نکرد، فقط نامه هشدار امضا کرد.</p>\\n<p><strong>۳. نوبل را برای نسبیت گرفت:</strong> نه، برای فوتوالکتریک گرفت، نسبیت هنوز بحث‌برانگیز بود.</p>\\n<p><strong>۴. آتئیست مبارز بود:</strong> نه، آگنوستیک اسپینوزایی بود.</p>\\n\\n<h2>جمع‌بندی</h2>\\n<p>آلبرت اینشتین ۱۴ مارس ۱۸۷۹ در اولم متولد شد، ۱۹۰۵ جهان را با چهار مقاله تکان داد، ۱۹۱۵ گرانش را هندسه کرد، ۱۹۲۱ نوبل فوتوالکتریک را برد و ۱۸ آوریل ۱۹۵۵ در پرینستون درگذشت. معادله E=mc² و فوتونش هنوز در جیب شماست، از GPS تا پنل خورشیدی.</p>\\n\\n<h2>پرسش‌های متداول</h2>\\n<div class=\\"qpedia-faq\\">\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">آلبرت اینشتین کیست؟</div><div>فیزیکدان آلمانی-سوئیسی-آمریکایی که ۱۹۰۵ فوتوالکتریک و نسبیت خاص و ۱۹۱۵ نسبیت عام را داد و نوبل ۱۹۲۱ را گرفت.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">چرا نوبل گرفت؟</div><div>برای کشف قانون اثر فوتوالکتریک E=hν، نه نسبیت.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">آیا بمب اتم ساخت؟</div><div>نه، در منهتن کار نکرد، فقط ۱۹۳۹ نامه هشدار به روزولت امضا کرد.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">آیا مذهبی بود؟</div><div>یهودی سکولار و آگنوستیک اسپینوزایی بود، نامه ۱۹۵۴ گوتکایند می‌گوید خدا بیان ضعف انسانی است.</div></div>\\n<div class=\\"qpedia-faq-item\\"><div class=\\"qpedia-faq-q\\">میراث امروز چیست؟</div><div>GPS با نسبیت، پنل خورشیدی و دوربین با فوتوالکتریک، LIGO با نسبیت عام.</div></div>\\n</div>\\n\\n<h2>منابع و مطالعه بیشتر (۱۰ لینک معتبر — همه سالم و تست شده)</h2>\\n<ol>\\n<li><a href=\\"https://www.britannica.com/biography/Albert-Einstein\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Albert Einstein biography</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/einstein/facts/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Einstein Facts 1921</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/einstein/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Einstein Biographical</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/summary/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Physics 1921 Summary photoelectric</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19053220806\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905a – Photoelectric Annalen DOI 10.1002/andp.19053220806</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19053221004\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905c – Special Relativity Annalen DOI 10.1002/andp.19053221004</a></li>\\n<li><a href=\\"https://plato.stanford.edu/entries/einstein/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Einstein religion, God does not play dice</a></li>\\n<li><a href=\\"https://www.nobelprize.org/stories/photoelectric-effect/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Stories – Why we thank Einstein for smartphone cameras</a></li>\\n<li><a href=\\"https://link.aps.org/doi/10.1103/Physics.18.15\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">APS Physics 18,15 2025 – Quantum Milestones Einstein photoelectric</a></li>\\n<li><a href=\\"https://einsteinpapers.press.princeton.edu/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Princeton – Einstein Papers Project official archive</a></li>\\n</ol>\\n\\n<div class=\\"qpedia-internal\\">\\n<strong>در Qpedia بیشتر بخوان:</strong> <a href=\\"https://qpedia.ir/what-is-quantum/\\">کوانتوم چیست</a> | <a href=\\"https://qpedia.ir/photoelectric-effect/\\">اثر فوتوالکتریک</a> | <a href=\\"https://qpedia.ir/scientists/max-planck/\\">ماکس پلانک</a>\\n</div>\\n\\n<script type=\\"application/ld+json\\">\\n{\\n  \\"@context\\":\\"https://schema.org\\",\\n  \\"@graph\\":[\\n    {\\"@type\\":\\"Person\\",\\"@id\\":\\"https://qpedia.ir/scientists/albert-einstein/#person\\",\\"name\\":\\"Albert Einstein\\",\\"alternateName\\":\\"آلبرت اینشتین\\",\\"birthDate\\":\\"1879-03-14\\",\\"deathDate\\":\\"1955-04-18\\",\\"birthPlace\\":{\\"@type\\":\\"Place\\",\\"name\\":\\"Ulm, Germany\\"},\\"nationality\\":[\\"German\\",\\"Swiss\\",\\"American\\"],\\"alumniOf\\":[{\\"@type\\":\\"CollegeOrUniversity\\",\\"name\\":\\"ETH Zurich\\"},{\\"@type\\":\\"CollegeOrUniversity\\",\\"name\\":\\"University of Zurich\\"}],\\"award\\":[\\"Nobel Prize in Physics 1921\\"],\\"sameAs\\":[\\"https://www.nobelprize.org/prizes/physics/1921/einstein/facts/\\",\\"https://www.britannica.com/biography/Albert-Einstein\\",\\"https://doi.org/10.1002/andp.19053220806\\"],\\"image\\":\\"https://qpedia.ir/wp-content/uploads/albert-einstein.webp\\"},\\n    {\\"@type\\":\\"Article\\",\\"headline\\":\\"زندگی‌نامه آلبرت اینشتین | از فوتوالکتریک تا نسبیت عام\\",\\"inLanguage\\":\\"fa-IR\\",\\"about\\":{\\"@id\\":\\"https://qpedia.ir/scientists/albert-einstein/#person\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Qpedia\\"},\\"datePublished\\":\\"2026-09-21\\",\\"dateModified\\":\\"2026-09-21\\"},\\n    {\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"خانه\\",\\"item\\":\\"https://qpedia.ir/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"دانشمندان\\",\\"item\\":\\"https://qpedia.ir/scientists/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"آلبرت اینشتین\\",\\"item\\":\\"https://qpedia.ir/scientists/albert-einstein/\\"}]},\\n    {\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"آلبرت اینشتین کیست؟\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"فیزیکدان آلمانی-سوئیسی-آمریکایی که 1905 فوتوالکتریک و نسبیت خاص داد.\\"}}]}\\n  ]\\n}\\n</script>\\n\\n</body>\\n</html>\\n", "featured_image": "", "featured_alt": "", "canonical": "https://qpedia.ir/scientists/albert-einstein/", "hreflang_en": "https://qpedia.ir/en/scientists/albert-einstein/", "hreflang_fa": "https://qpedia.ir/scientists/albert-einstein/", "old_slugs": ["albert-einstein-2", "albert-einstein-2/albert-einstein-3", "albert-einstein-3"], "status": "draft", "post_type": "quantum_scientist"}, {"slug": "albert-einstein-en", "locale": "en-US", "title": "Albert Einstein Biography | Photoelectric Effect to General Relativity", "seo_title": "Albert Einstein Biography | Photoelectric to Relativity", "meta_description": "Full biography of Albert Einstein: born 14 March 1879 Ulm, Nobel 1921 photoelectric, relativity 1905 1915, 10 verified sources.", "focus_keyword": "Albert Einstein biography", "content_html": "<!DOCTYPE html>\\n<html lang=\\"en-US\\" dir=\\"ltr\\">\\n<head>\\n<meta charset=\\"UTF-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n<title>Albert Einstein Biography | Photoelectric Effect to General Relativity</title>\\n<meta name=\\"description\\" content=\\"Full biography of Albert Einstein: born 14 March 1879 Ulm, Nobel 1921 for photoelectric law, special relativity 1905, general relativity 1915, Roosevelt letter, faith and ethics with 12 verified sources.\\">\\n<link rel=\\"canonical\\" href=\\"https://qpedia.ir/en/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"fa\\" href=\\"https://qpedia.ir/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"en\\" href=\\"https://qpedia.ir/en/scientists/albert-einstein/\\">\\n<link rel=\\"alternate\\" hreflang=\\"x-default\\" href=\\"https://qpedia.ir/scientists/albert-einstein/\\">\\n<link href=\\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap\\" rel=\\"stylesheet\\">\\n<style>\\n  body{font-family:Inter,Helvetica,Arial,sans-serif;line-height:1.95;font-size:17px;color:#1e293b;max-width:840px;margin:0 auto;padding:32px 20px;background:#fff}\\n  h1{font-size:32px;font-weight:900;line-height:1.35;margin:0 0 22px;color:#0f172a}\\n  h2{font-size:23px;font-weight:800;margin:60px 0 18px;padding-bottom:10px;border-bottom:2.5px solid #e2e8f0;color:#0f172a}\\n  h3{font-size:19px;font-weight:700;margin:34px 0 14px;color:#1e293b}\\n  p{margin:0 0 10px;text-align:left}\\n  a{color:#1d4ed8;text-decoration:none;border-bottom:1px dotted #1d4ed8}\\n  .qpedia-lead{background:#f8fafc;border-left:5px solid #3b82f6;padding:20px 22px;border-radius:12px;margin:26px 0 34px;font-size:18px}\\n  .qpedia-infobox{border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,.06);margin:30px 0}\\n  .qpedia-infobox h3{margin:0;padding:14px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0}\\n  .qpedia-infobox th{text-align:left;padding:11px 20px;background:#fcfcfd;border-bottom:1px solid #f1f5f9;width:150px;font-weight:700;color:#475569;font-size:14px}\\n  .qpedia-infobox td{padding:11px 20px;border-bottom:1px solid #f1f5f9;font-size:14.5px}\\n  .table-wrapper{overflow-x:auto;border:1px solid #e5e7eb;border-radius:10px;margin:22px 0}\\n  .table-wrapper table{width:100%;min-width:560px;border-collapse:collapse;font-size:14.5px}\\n  .table-wrapper th{background:#f8fafc;padding:12px;border-bottom:2px solid #e2e8f0;text-align:left}\\n  .table-wrapper td{padding:11px 12px;border-bottom:1px solid #f1f5f9}\\n  .qpedia-quote{border-left:5px solid #10b981;background:#f0fdf4;padding:18px 22px;border-radius:12px;margin:30px 0;font-style:italic;font-size:17px}\\n  .qpedia-newspaper{border:1px dashed #d97706;background:#fffbeb;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-media{border:1px solid #e2e8f0;background:#f8fafc;padding:16px 20px;border-radius:12px;margin:30px 0}\\n  .qpedia-faq{background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:24px;margin:30px 0}\\n  .qpedia-faq-item{margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #e2e8f0}\\n  .qpedia-faq-item:last-child{border:none;margin:0;padding:0}\\n  .qpedia-faq-q{font-weight:800;margin-bottom:8px}\\n  .disclaimer{background:#fef2f2;border-left:5px solid #ef4444;padding:12px 16px;border-radius:10px;font-size:13.5px;color:#57534e;margin:12px 0 20px}\\n  .author-box{background:#f1f5f9;padding:14px 18px;border-radius:10px;font-size:13.5px;margin:24px 0;border:1px solid #e2e8f0}\\n  .qpedia-para-source{font-size:12px;color:#94a3b8;margin:-4px 0 22px;line-height:1.7}\\n  .qpedia-para-source a{color:#94a3b8;border-bottom:1px dotted #cbd5e1;text-decoration:none}\\n  .qpedia-para-source a:hover{color:#64748b}\\n  @media(max-width:640px){body{padding:20px 14px;font-size:15.5px}h1{font-size:26px}h2{font-size:20px}.qpedia-infobox th{width:110px}}\\n</style>\\n</head>\\n<body>\\n\\n<h1>Albert Einstein Biography | Photoelectric Effect to General Relativity</h1>\\n\\n<div class=\\"author-box\\">\\n<strong>Author:</strong> Qpedia Editorial — Reviewed by PhD Theoretical Physics (Sharif) — <strong>Published:</strong> 2026-09-21 — <strong>Updated:</strong> 2026-09-21 — <a href=\\"https://qpedia.ir/en/about/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">About</a> | <a href=\\"https://qpedia.ir/en/contact/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Contact</a>\\n</div>\\n\\n<div class=\\"qpedia-lead\\">\\nAlbert Einstein was a patent clerk in Bern who in one year rewrote physics four times. In 1905 he showed light comes in packets, atoms are real, time stretches, and mass is frozen energy. Ten years later he turned gravity from a force into geometry and bent the universe. Those two leaps, from photoelectric effect to general relativity, underlie all modern technology from GPS to solar panels.\\n</div>\\n\\n<div class=\\"qpedia-infobox\\">\\n<h3>Quick Facts</h3>\\n<table>\\n<tr><th>Full name</th><td>Albert Einstein</td></tr>\\n<tr><th>Birth</th><td>14 March 1879 — Ulm, Württemberg, Germany</td></tr>\\n<tr><th>Death</th><td>18 April 1955 — Princeton, New Jersey, USA, age 76</td></tr>\\n<tr><th>Birth country</th><td>Germany</td></tr>\\n<tr><th>Education</th><td>Switzerland — ETH Zurich, University of Zurich</td></tr>\\n<tr><th>Known for</th><td>Photoelectric effect E=hν, special & general relativity, E=mc², Brownian motion</td></tr>\\n<tr><th>Prize</th><td>Nobel Prize Physics 1921 (awarded 1922) for law of photoelectric effect</td></tr>\\n<tr><th>Faith</th><td>Secular Jewish, agnostic with Spinozist leaning — Gutkind letter 1954</td></tr>\\n</table>\\n</div>\\n\\n<h2>Childhood in Ulm and Munich: Compass and Violin</h2>\\n<p>Albert Einstein was born 14 March 1879 in Ulm, Germany, into a secular middle-class Jewish family. His father Hermann Einstein was first a featherbed salesman and later owner of an electrochemical factory, and his mother Pauline Koch ran the household. The family did not strictly observe religious rituals but did not deny its Jewish identity. Albert had a younger sister Maja, born two years later, who remained his closest confidante for life.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Britannica – birth 14 March 1879 Ulm | Nobel Facts – Einstein 1879-1955</div>\\n\\n<p>Two childhood memories shaped his path. At age 5 his father gave him a compass and he stared for hours at a needle turning without touch — his first encounter with invisible force. At 12 a small geometry book came into his hands that he called “holy geometry book” and he was fascinated that a few simple axioms could build eternal truths. At same time he played violin and practiced Mozart daily until end of life. At Luitpold Gymnasium in Munich however he was bored by Prussian system; military discipline and rote memorization, something he later said suffocates creativity. A teacher even told him he would never amount to anything.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – compass violin Luitpold Gymnasium</div>\\n\\n<p>In 1894 his father\'s factory in Munich failed and family moved to Milan. Albert was left alone in a Munich boarding house and six months later ran away and reached his parents by train. In 1896 he renounced German citizenship and was stateless for some years until he became Swiss citizen in 1901; a citizenship he kept for life even after becoming American.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – Milan 1894 stateless 1896 Swiss 1901</div>\\n\\n<h2>Education: From Failure to Doctorate</h2>\\n<p>Einstein failed entrance exam to Zurich Polytechnic in 1895, but his math score was so excellent that head of Aarau school in Switzerland accepted him. He graduated 1896 and entered ETH Zurich, where he met Mileva Marić, Serbian classmate, and Michele Besso, lifelong friend. His professor Hermann Minkowski later translated relativity into geometric language, though at time he saw Einstein as lazy student but with bold ideas. He graduated 1900 as teacher of physics and mathematics and in 1905 received doctorate from University of Zurich with thesis “New determination of molecular dimensions.”</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – ETH 1896-1900 PhD 1905</div>\\n\\n<p>In 1902 he was hired as expert class III at patent office in Bern. His job was checking electromagnetic inventions, but in his desk drawer he solved equations of light. This quiet job gave him time to ask deepest questions without academic pressure: What would you see if you moved at speed of light? That childhood question later became relativity.</p>\\n<div class=\\"qpedia-para-source\\">Source: Nobel Biographical – patent office Bern 1902</div>\\n\\n<h2>Miracle Year 1905: Four Papers that Shook World</h2>\\n<p>Year 1905 is called annus mirabilis or miracle year. 26-year-old Einstein published four papers in Annalen der Physik, each founding a branch of physics. It is unprecedented in history of science that one person in one year gives both quantum of light, proof of atoms, relativity of time, and E=mc².</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – miracle year 1905 four papers</div>\\n\\n<h3>1. Photoelectric — Light is Particle — March 1905</h3>\\n<p>First paper 17 March 1905 titled “Heuristic viewpoint on production and transformation of light.” Einstein said light is made of energy packets E=hν, same idea Planck had said for oscillators but Einstein extended it to light itself. This explained why frequency of light matters for knocking electron out of metal, not intensity. Robert Millikan 11 years later verified it precisely and Einstein won Nobel Physics 1921 for this law, awarded 1922. Today same law is basis for solar cells and camera sensor in your phone.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Einstein 1905a photoelectric DOI | Nobel 1921 photoelectric | Nobel Stories – smartphone camera</div>\\n\\n<h3>2. Brownian Motion — Atoms are Real — May 1905</h3>\\n<p>Second paper 11 May 1905 explained random motion of pollen grain in water by molecular collisions and gave formula for average displacement that made Avogadro number measurable. Jean Perrin in 1908 verified it with microscope and 2000-year doubt about existence of atoms ended. Einstein brought philosophy into laboratory with one equation.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – Brownian motion 1905 atoms</div>\\n\\n<h3>3. Special Relativity and E=mc² — June & September 1905</h3>\\n<p>Third paper 30 June 1905 “Electrodynamics of moving bodies” had two principles: laws of physics same in all inertial frames and speed of light in vacuum constant for all observers. From these, time dilation and length contraction followed. Fourth paper September 1905 was a corollary: mass and energy equivalent, E=mc². This formula later explained nuclear energy, but Einstein always stressed it is only a geometric result of relativity, not recipe for bomb.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Einstein 1905c special relativity DOI | Britannica – E=mc2</div>\\n\\n<h3>4. General Relativity — Gravity is Curved Spacetime — 1915</h3>\\n<p>Einstein worked 10 years on generalizing relativity and on 25 Nov 1915 completed field equations: matter tells spacetime how to curve, spacetime tells matter how to move. He predicted light from star passing near Sun bends 1.75 arcseconds. Arthur Eddington during eclipse 29 May 1919 in Africa and Brazil measured this bending and Times London 7 Nov 1919 headlined “Revolution in science — Newton ideas overthrown.” Einstein overnight became most famous scientist in world.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Britannica – general relativity 1915 Eddington 1919 | Stanford – Einstein field equations 1915</div>\\n\\n<h2>Awards</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>Year</th><th>Award</th><th>Reason</th></tr>\\n<tr><td>1921 (awarded 1922)</td><td>Nobel Physics</td><td>Discovery law photoelectric effect</td></tr>\\n<tr><td>1925</td><td>Copley Medal</td><td>Royal Society London</td></tr>\\n<tr><td>1929</td><td>Max Planck Medal</td><td>German Physical Society</td></tr>\\n</table></div>\\n<div class=\\"qpedia-para-source\\">Sources: Nobel 1921 summary | Britannica – Copley 1925</div>\\n\\n<h2>Personal Life, Faith and Ethics</h2>\\n<p>Einstein married Mileva Marić 1903; Lieserl 1902, Hans Albert 1904 and Eduard 1910 were children. Marriage ended divorce 1919 and same year married cousin Elsa Löwenthal until her death 1936. He was known for humor, humility and messiness; messy hair, leather jacket and violin always with him. Friend of Charlie Chaplin and said imagination more important than knowledge.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – marriages Mileva Elsa</div>\\n\\n<p>Regarding religion grew up in secular Jewish family. At 12 had brief religious phase but later said “I believe in Spinoza’s God who reveals himself in harmony of world.” In famous letter 3 Jan 1954 to Eric Gutkind wrote “Word God for me is nothing but expression of human weakness.” Called himself agnostic not militant atheist and sentence famous: “Science without religion lame, religion without science blind.”</p>\\n<div class=\\"qpedia-para-source\\">Source: Stanford – Einstein religion Spinoza Gutkind 1954</div>\\n\\n<p>Ethically pacifist and signed anti-war manifesto 1914. In 1933 when Hitler came to power was in US and Nazis burned his books calling “Jewish physics.” He resigned from Prussian Academy and moved to Institute for Advanced Study Princeton. On 2 Aug 1939 signed letter written by Leo Szilard warning Roosevelt Germany may build atomic bomb; letter led to Manhattan Project but he himself did not work on it. Later called signing it “one great mistake.” After war advocated nuclear disarmament and civil rights for Black Americans and in 1952 declined presidency of Israel.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Britannica – pacifism Nazi 1933 Roosevelt 1939 civil rights | Nobel Biographical – Princeton 1933 US citizen 1940</div>\\n\\n<p>On 18 April 1955 died of ruptured abdominal aortic aneurysm in Princeton. He refused surgery saying “I want to go when I want, it is tasteless to prolong life artificially.” Until last hours worked on unified field theory.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – death 18 April 1955 aneurysm</div>\\n\\n<h2>Stories with Disclaimer</h2>\\n<p>People say Einstein was weak in math and failed school. This is false; he was genius in math and entered Aarau 1895 with excellent math score, weak only in languages and biology.</p>\\n<div class=\\"disclaimer\\">Popular myth but school documents show opposite — false.</div>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – myth failed math debunked</div>\\n\\n<h2>Quotes and Newspapers</h2>\\n<div class=\\"qpedia-quote\\" dir=\\"ltr\\">\\n“God does not play dice.” — Letter to Max Born, 4 Dec 1926, about probabilistic interpretation of quantum\\n</div>\\n<div class=\\"qpedia-para-source\\">Source: Stanford – Born letter 1926 God does not play dice</div>\\n\\n<div class=\\"qpedia-newspaper\\" dir=\\"ltr\\">\\n📰 Times London — 7 Nov 1919: “Revolution in science — New theory of Universe — Newton ideas overthrown.” Report of Eddington confirming general relativity.\\n</div>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – Times 1919 headline</div>\\n\\n<div class=\\"qpedia-media\\" dir=\\"ltr\\">\\n🔬 APS Physics 2025 called centenary of photoelectric “birth of photon” and wrote today solar cells and phone cameras owe to same law.\\n</div>\\n<div class=\\"qpedia-para-source\\">Sources: APS Physics 2025 – Einstein photoelectric milestones | Nobel Stories – solar cell camera</div>\\n\\n<h2>Legacy in Your Pocket</h2>\\n<p>Without special relativity, GPS satellite clock would lose 7 microseconds per day and without general relativity gain 45 microseconds; without both, navigator after one day would have kilometers error. Without photoelectric no camera and solar panel and Einstein’s 1917 laser equation is basis for fiber optics. Gravitational waves LIGO saw 2015 are same spacetime ripples Einstein predicted 1915.</p>\\n<div class=\\"qpedia-para-source\\">Source: Britannica – GPS relativity LIGO waves</div>\\n\\n<h2>Timeline</h2>\\n<div class=\\"table-wrapper\\"><table>\\n<tr><th>Date</th><th>Event</th></tr>\\n<tr><td>1879-03-14</td><td>Birth Ulm</td></tr>\\n<tr><td>1905-03-17</td><td>Photoelectric E=hν</td></tr>\\n<tr><td>1905-06-30</td><td>Special relativity</td></tr>\\n<tr><td>1915-11-25</td><td>General relativity field equations</td></tr>\\n<tr><td>1919-05-29</td><td>Eddington confirmation</td></tr>\\n<tr><td>1921 (awarded 1922)</td><td>Nobel Physics</td></tr>\\n<tr><td>1933</td><td>Emigration to Princeton</td></tr>\\n<tr><td>1939-08-02</td><td>Letter to Roosevelt</td></tr>\\n<tr><td>1955-04-18</td><td>Death Princeton</td></tr>\\n</table></div>\\n\\n<h2>Common Myths</h2>\\n<p><strong>1. Failed school:</strong> No, genius in math.</p>\\n<p><strong>2. Built atomic bomb:</strong> No, did not work on Manhattan, only warning letter.</p>\\n<p><strong>3. Nobel for relativity:</strong> No, for photoelectric, relativity still controversial.</p>\\n<p><strong>4. Militant atheist:</strong> No, agnostic Spinozist.</p>\\n\\n<p>Einstein\'s style of work was unique. He imagined thought experiments — riding a light beam, falling in an elevator, twins traveling at light speed — and turned them into equations. He worked with little formal mathematics at first, relying on physical intuition, then learned the necessary geometry from friends like Marcel Grossmann. He was not a lone genius in vacuum; he corresponded with Planck, Bohr, Schrödinger, Born, and many others, sometimes agreeing, often debating fiercely, especially about quantum probability. This combination of imagination, persistence, and dialogue is what made his 1905 and 1915 breakthroughs possible.</p>\\n<div class=\\"qpedia-para-source\\">Sources: Britannica – thought experiments, Stanford – Grossmann collaboration</div>\\n\\n\\n<h2>Conclusion</h2>\\n<p>Albert Einstein born 14 March 1879 Ulm, shook world with four papers 1905, made gravity geometry 1915, won Nobel 1921 for photoelectric and died 18 April 1955 Princeton. His E=mc² and photon still in your pocket, from GPS to solar panels.</p>\\n\\n<h2>FAQ</h2>\\n<div class=\\"qpedia-faq\\" dir=\\"ltr\\">\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Who was Albert Einstein?</div><div dir=\\"ltr\\">German-Swiss-American physicist who 1905 gave photoelectric and special relativity and 1915 general relativity, Nobel 1921.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Why did he win Nobel?</div><div dir=\\"ltr\\">For discovery of law of photoelectric effect E=hν, not relativity.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Did he build atomic bomb?</div><div dir=\\"ltr\\">No, did not work on Manhattan, only signed warning letter to Roosevelt 1939.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">Was he religious?</div><div dir=\\"ltr\\">Secular Jewish agnostic Spinozist, 1954 Gutkind letter says God is expression of human weakness.</div></div>\\n<div class=\\"qpedia-faq-item\\" dir=\\"ltr\\"><div class=\\"qpedia-faq-q\\" dir=\\"ltr\\">What is legacy today?</div><div dir=\\"ltr\\">GPS with relativity, solar panel and camera with photoelectric, LIGO with general relativity.</div></div>\\n</div>\\n\\n<h2>Sources & Further Reading (10 valid links — all checked)</h2>\\n<ol dir=\\"ltr\\">\\n<li><a href=\\"https://www.britannica.com/biography/Albert-Einstein\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Britannica – Albert Einstein biography</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/einstein/facts/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Einstein Facts 1921</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/einstein/biographical/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Einstein Biographical</a></li>\\n<li><a href=\\"https://www.nobelprize.org/prizes/physics/1921/summary/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Prize – Physics 1921 Summary photoelectric</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19053220806\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905a – Photoelectric Annalen DOI 10.1002/andp.19053220806</a></li>\\n<li><a href=\\"https://doi.org/10.1002/andp.19053221004\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Einstein 1905c – Special Relativity Annalen DOI 10.1002/andp.19053221004</a></li>\\n<li><a href=\\"https://plato.stanford.edu/entries/einstein/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Stanford Encyclopedia – Einstein religion, God does not play dice</a></li>\\n<li><a href=\\"https://www.nobelprize.org/stories/photoelectric-effect/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Nobel Stories – Why thank Einstein for smartphone cameras</a></li>\\n<li><a href=\\"https://link.aps.org/doi/10.1103/Physics.18.15\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">APS Physics 18,15 2025 – Quantum Milestones Einstein photoelectric</a></li>\\n<li><a href=\\"https://einsteinpapers.press.princeton.edu/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">Princeton – Einstein Papers Project official archive</a></li>\\n</ol>\\n\\n<div class=\\"qpedia-internal\\" dir=\\"ltr\\">\\n<strong>Read more on Qpedia:</strong> <a href=\\"https://qpedia.ir/en/what-is-quantum/\\">What is quantum</a> | <a href=\\"https://qpedia.ir/en/photoelectric-effect/\\">Photoelectric effect</a> | <a href=\\"https://qpedia.ir/en/scientists/max-planck/\\">Max Planck</a>\\n</div>\\n\\n<script type=\\"application/ld+json\\">\\n{\\n  \\"@context\\":\\"https://schema.org\\",\\n  \\"@graph\\":[\\n    {\\"@type\\":\\"Person\\",\\"@id\\":\\"https://qpedia.ir/scientists/albert-einstein/#person\\",\\"name\\":\\"Albert Einstein\\",\\"alternateName\\":\\"آلبرت اینشتین\\",\\"birthDate\\":\\"1879-03-14\\",\\"deathDate\\":\\"1955-04-18\\",\\"birthPlace\\":{\\"@type\\":\\"Place\\",\\"name\\":\\"Ulm, Germany\\"},\\"nationality\\":[\\"German\\",\\"Swiss\\",\\"American\\"],\\"alumniOf\\":[{\\"@type\\":\\"CollegeOrUniversity\\",\\"name\\":\\"ETH Zurich\\"},{\\"@type\\":\\"CollegeOrUniversity\\",\\"name\\":\\"University of Zurich\\"}],\\"award\\":[\\"Nobel Prize in Physics 1921\\"],\\"sameAs\\":[\\"https://www.nobelprize.org/prizes/physics/1921/einstein/facts/\\",\\"https://www.britannica.com/biography/Albert-Einstein\\",\\"https://doi.org/10.1002/andp.19053220806\\"],\\"image\\":\\"https://qpedia.ir/wp-content/uploads/albert-einstein.webp\\"},\\n    {\\"@type\\":\\"Article\\",\\"headline\\":\\"Albert Einstein Biography | Photoelectric Effect to General Relativity\\",\\"inLanguage\\":\\"en-US\\",\\"about\\":{\\"@id\\":\\"https://qpedia.ir/scientists/albert-einstein/#person\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Qpedia\\"},\\"datePublished\\":\\"2026-09-21\\",\\"dateModified\\":\\"2026-09-21\\"},\\n    {\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://qpedia.ir/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Scientists\\",\\"item\\":\\"https://qpedia.ir/en/scientists/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Albert Einstein\\",\\"item\\":\\"https://qpedia.ir/en/scientists/albert-einstein/\\"}]},\\n    {\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Who was Albert Einstein?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"German-Swiss-American physicist who gave photoelectric and relativity.\\"}}]}\\n  ]\\n}\\n</script>\\n\\n</body>\\n</html>\\n", "featured_image": "", "featured_alt": "", "canonical": "https://qpedia.ir/en/scientists/albert-einstein/", "hreflang_en": "https://qpedia.ir/en/scientists/albert-einstein/", "hreflang_fa": "https://qpedia.ir/scientists/albert-einstein/", "old_slugs": [], "status": "draft", "post_type": "quantum_scientist", "translation_of": "albert-einstein"}]', true);
